function d(i,a){const n=r=>{const e=parseFloat(r);return isNaN(e)?0:e};if(i==="bmi"){const r=n(a.weight),e=n(a.height);if(r<=0||e<=0)return{ok:!1,error:"Ingrese peso y altura"};const o=r/(e*e),s=o.toFixed(1);let t="",l="";return o<18.5?(t="Bajo peso",l="#333"):o<25?(t="Peso normal",l="green"):o<30?(t="Sobrepeso",l="orange"):o<35?(t="Obesidad G1",l="red"):o<40?(t="Obesidad G2",l="darkred"):(t="Obesidad G3",l="purple"),{ok:!0,text:`<span style="color:${l}">${s} - ${t}</span>`,value:o}}if(i==="homa_ir"){const r=n(a.glucose),e=n(a.insulin);if(r<=0||e<=0)return{ok:!1,error:"Faltan datos"};const o=r*e/405,s=o.toFixed(2),t=o>2.5;return{ok:!0,text:`<span style="color:${t?"red":"green"}">${s} (${t?"Posible Resistencia":"Rango Normal"})</span>`,value:o}}if(i==="ldl_calc"){const r=n(a.tc),e=n(a.hdl),o=n(a.tg);if(r<=0||e<=0||o<=0)return{ok:!1,error:"Faltan valores"};if(o>=400)return{ok:!1,error:"TG > 400: Fórmula no válida (pedir LDL directo)"};const s=r-e-o/5,t=s.toFixed(0);let l="green";return t>190?l="darkred":t>160?l="red":t>130&&(l="orange"),{ok:!0,text:`LDL Calculado: <strong style="color:${l}">${t} mg/dL</strong>`,value:s}}if(i==="map_calc"){const r=n(a.sys),e=n(a.dia);if(r<=0||e<=0)return{ok:!1,error:"Faltan valores"};const o=(r+2*e)/3,s=o.toFixed(0);let t="green",l="Perfusión adecuada";return s<65?(t="red",l="Hipoperfusión (Riesgo Shock)"):s>110&&(t="orange",l="Elevada"),{ok:!0,text:`PAM: <strong style="color:${t}">${s} mmHg</strong><br><small>${l}</small>`,value:o}}if(i==="levo_dose"){const r=n(a.weight);if(r<=0)return{ok:!1,error:"Ingrese peso"};const e=(r*1.6).toFixed(0),o=(r*1.8).toFixed(0);return{ok:!0,text:`Dosis Plena Sugerida:<br><strong style="color:#0066cc">${e} - ${o} mcg/día</strong>`,value:e}}if(i==="hr_target"){const r=n(a.age);if(r<=0||r>120)return{ok:!1,error:"Edad inválida"};const e=220-r,o=(e*.64).toFixed(0),s=(e*.76).toFixed(0);return{ok:!0,text:`Máximo Teórico: ${e} lpm<br>Zona Objetivo: <strong style="color:#0066cc">${o} - ${s} lpm</strong>`,value:e}}if(i==="water_calc"){const r=n(a.weight);if(r<=0)return{ok:!1,error:"Ingrese peso"};const e=r*35,o=(e/1e3).toFixed(1),s=(e/250).toFixed(0);return{ok:!0,text:`Meta Diaria: <strong style="color:#0066cc">${o} Litros</strong><br><small>(Aprox. ${s} vasos de agua)</small>`,value:e}}if(i==="sleep_eff"){const r=n(a.bed_time),e=n(a.sleep_time);if(r<=0||e<=0)return{ok:!1,error:"Datos inválidos"};if(e>r)return{ok:!1,error:"No puede dormir más tiempo del que está en cama"};const o=(e/r*100).toFixed(0);let s="green",t="Sueño Saludable";return o<75?(s="red",t="Insomnio / Fragmentación"):o<85&&(s="orange",t="Baja Eficiencia"),{ok:!0,text:`Eficiencia: <strong style="color:${s}">${o}%</strong><br><small>${t}</small>`,value:o}}return{ok:!1,error:`Calculadora '${i}' no encontrada`}}export{d as runCalculator};
